func (this *Display) FindLatinKeyGroup() int32 {
	var result int32 = 0
	this.groupKeysCount = jrt.NewMap()
	var display int64 = gtk.GDKGdk_display_get_default()
	for keyval := int32(gtk.GDKGDK_KEY_a); keyval <= gtk.GDKGDK_KEY_z; keyval++ {
		var keys []int64 = make([]int64, 1)
		var n_keys []int32 = make([]int32, 1)
		var foundKeys bool
		if gtk.GTKGTK4 {
			foundKeys = gtk.GDKGdk_display_map_keyval(display, keyval, keys, n_keys)
		} else {
			var keymap int64 = gtk.GDKGdk_keymap_get_for_display(display)
			foundKeys = gtk.GDKGdk_keymap_get_entries_for_keyval(keymap, keyval, keys, n_keys)
		}
		if foundKeys {
			var key_entry gtk.GdkKeymapKey = gtk.GdkKeymapKey{}
			for key := int32(0); key < n_keys[0]; key++ {
				gtk.OSMemmoveOverload9(&key_entry, keys[0]+int64(key*gtk.GdkKeymapKeySizeof), int64(gtk.GdkKeymapKeySizeof))
				var keys_count any = any(this.groupKeysCount.Get(int32(key_entry.Group)))
				if !jrt.IsNil(keys_count) {
					keys_count = jrt.Cast[int32](keys_count) + 1
				} else {
					keys_count = int32(1)
				}
				this.groupKeysCount.Put(int32(key_entry.Group), keys_count)
			}
			gtk.OSG_free(keys[0])
		}
	}
	var max_keys_count int32 = 0
	for _, elem257 := range this.groupKeysCount.EntrySet().ToArray() {
		entry := jrt.Cast[*jrt.MapEntry](elem257)
		var group any = entry.GetKey()
		var keys_count any = entry.GetValue()
		if jrt.Cast[int32](keys_count) > max_keys_count {
			result = jrt.Cast[int32](group)
			max_keys_count = jrt.Cast[int32](keys_count)
		}
	}
	return result
}

