func (this *Display) GetWorkArea() *Rectangle {
	var name []int8 = gtk.ConverterWcsToMbcs("_NET_WORKAREA", true)
	var atom int64 = gtk.GDKGdk_atom_intern(name, true)
	if atom == int64(gtk.GDKGDK_NONE) {
		return nil
	}
	var actualType []int64 = make([]int64, 1)
	var actualFormat []int32 = make([]int32, 1)
	var actualLength []int32 = make([]int32, 1)
	var data []int64 = make([]int64, 1)
	if !gtk.GDKGdk_property_get(gtk.GDKGdk_get_default_root_window(), atom, int64(gtk.GDKGDK_NONE), int64(0), int64(16), 0, actualType, actualFormat, actualLength, data) {
		return nil
	}
	var result *Rectangle = nil
	if data[0] != 0 {
		if actualLength[0] == 16 {
			var values []int32 = make([]int32, 4)
			gtk.CMemmoveOverload15(values, data[0], int64(16))
			result = NewRectangle(values[0], values[1], values[2], values[3])
		} else {
			if actualLength[0] == 32 {
				var values []int64 = make([]int64, 4)
				gtk.CMemmoveOverload16(values, data[0], int64(32))
				result = NewRectangle(int32(values[0]), int32(values[1]), int32(values[2]), int32(values[3]))
			}
		}
		gtk.OSG_free(data[0])
	}
	return result
}

func (this *Display) GetMonitors() []*Monitor {
	this.impl.checkDevice_()
	var monitors []*Monitor = nil
	var workArea *Rectangle = this.GetWorkArea()
	var display int64 = gtk.GDKGdk_display_get_default()
	if display != 0 {
		var monitorCount int32
		var monitorList int64 = int64(0)
		if gtk.GTKGTK4 {
			monitorList = gtk.GDKGdk_display_get_monitors(display)
			monitorCount = gtk.OSG_list_model_get_n_items(monitorList)
		} else {
			monitorCount = gtk.GDKGdk_display_get_n_monitors(display)
		}
		if monitorCount > 0 {
			monitors = make([]*Monitor, monitorCount)
			var geometry gtk.GdkRectangle = gtk.GdkRectangle{}
			for i := int32(0); i < monitorCount; i++ {
				var gdkMonitor int64
				if gtk.GTKGTK4 {
					gdkMonitor = gtk.OSG_list_model_get_item(monitorList, i)
				} else {
					gdkMonitor = gtk.GDKGdk_display_get_monitor(display, i)
				}
				gtk.GDKGdk_monitor_get_geometry(gdkMonitor, &geometry)
				var monitor *Monitor = newMonitor()
				monitor.handle = gdkMonitor
				monitor.x = geometry.X
				monitor.y = geometry.Y
				monitor.width = geometry.Width
				monitor.height = geometry.Height
				if !gtk.OSIsX11() || gtk.GTKGTK4 {
					var scaleFactor int32 = int32(gtk.GDKGdk_monitor_get_scale_factor(gdkMonitor))
					monitor.zoom = scaleFactor * 100
				} else {
					monitor.zoom = this._getDeviceZoom(monitor.handle)
				}
				if !gtk.GTKGTK4 {
					gtk.GDKGdk_monitor_get_workarea(gdkMonitor, &geometry)
				}
				monitor.clientX = geometry.X
				monitor.clientY = geometry.Y
				monitor.clientWidth = geometry.Width
				monitor.clientHeight = geometry.Height
				monitors[i] = monitor
			}
		}
	}
	if monitors == (nil) {
		var monitor *Monitor = newMonitor()
		var bounds *Rectangle = this.impl.getBounds_()
		monitor.x = bounds.X
		monitor.y = bounds.Y
		monitor.width = bounds.Width
		monitor.height = bounds.Height
		if workArea != (nil) {
			monitor.clientX = workArea.X
			monitor.clientY = workArea.Y
			monitor.clientWidth = workArea.Width
			monitor.clientHeight = workArea.Height
		} else {
			monitor.clientX = monitor.x
			monitor.clientY = monitor.y
			monitor.clientWidth = monitor.width
			monitor.clientHeight = monitor.height
		}
		monitors = []*Monitor{monitor}
	}
	return monitors
}

func (this *Display) GetPrimaryMonitor() *Monitor {
	this.impl.checkDevice_()
	var monitors []*Monitor = this.GetMonitors()
	var primaryMonitorIndex int32 = 0
	if gtk.GTKGTK4 {
		primaryMonitorIndex = 0
	} else {
		var display int64 = gtk.GDKGdk_display_get_default()
		var monitor int64 = gtk.GDKGdk_display_get_primary_monitor(display)
		for i := int32(0); i < int32(len(monitors)); i++ {
			var toCompare int64 = gtk.GDKGdk_display_get_monitor(display, i)
			if toCompare == monitor {
				primaryMonitorIndex = i
				break
			}
		}
	}
	return monitors[primaryMonitorIndex]
}

func (this *Display) GetShells() []*Shell {
	this.impl.checkDevice_()
	var index int32 = 0
	var result []*Shell = make([]*Shell, 16)
	for i := int32(0); i < int32(len(this.widgetTable)); i++ {
		var widget *Widget = this.widgetTable[i]
		_, ok265 := isWidgetToShell(widget)
		if !(ok265) {
			continue
		}
		if !widget.IsDisposed() {
			var j int32 = 0
			for j < index {
				if upcastShellToWidget(result[j]) == widget {
					break
				}
				j++
			}
			if j == index {
				if index == int32(len(result)) {
					var newResult []*Shell = make([]*Shell, index+16)
					copy(newResult[0:], result[0:0+index])
					result = newResult
				}
				t266 := index
				index++
				result[t266] = castWidgetToShell(widget)
			}
		} else {
			fmt.Fprintln(os.Stderr, fmt.Sprintf("SWT ERROR: disposed shell detected in the table%s", this.DebugInfoForIndex(int64(i))))
			for j := int32(i); j < int32(len(this.widgetTable)); j++ {
				if this.widgetTable[j] == widget {
					this.widgetTable[j] = nil
				}
			}
		}
	}
	if index == int32(len(result)) {
		return result
	}
	var newResult []*Shell = make([]*Shell, index)
	copy(newResult[0:], result[0:0+index])
	return newResult
}

