func (this *Display) GetSyncThread() any {
	jrt.MonitorEnter()
	var tret267 any
	tretd268 := false
	func() {
		defer jrt.MonitorExit()
		if this.IsDisposed() {
			this.Error(ERROR_DEVICE_DISPOSED)
		}
		tret267 = this.synchronizer.syncThread
		tretd268 = true
		return
	}()
	_ = tretd268
	return tret267
}

