func (this *Display) ToGdkRGBA(rgba gtk.GdkRGBA, brightness float64) gtk.GdkRGBA {
	var newRGBA gtk.GdkRGBA = gtk.GdkRGBA{}
	newRGBA.Alpha = rgba.Alpha
	var hue []float64 = make([]float64, 1)
	var saturationHSV []float64 = make([]float64, 1)
	var value []float64 = make([]float64, 1)
	if gtk.GTKGTK4 {
		var h []float32 = make([]float32, 1)
		var s []float32 = make([]float32, 1)
		var v []float32 = make([]float32, 1)
		gtk.GTK4Gtk_rgb_to_hsv(float32(rgba.Red), float32(rgba.Green), float32(rgba.Blue), h, s, v)
		hue[0] = float64(h[0])
		saturationHSV[0] = float64(s[0])
		value[0] = float64(v[0])
	} else {
		gtk.GTK3Gtk_rgb_to_hsv(rgba.Red, rgba.Green, rgba.Blue, hue, saturationHSV, value)
	}
	var luminosity float64 = ((2 - saturationHSV[0]) * value[0]) / 2
	var saturationHSL float64 = saturationHSV[0] * value[0]
	var cond269 float64
	if luminosity <= 1 {
		cond269 = luminosity
	} else {
		cond269 = 2 - luminosity
	}
	saturationHSL /= cond269
	saturationHSL = float64(math.Max(float64(0), float64(float64(math.Min(float64(1), float64(saturationHSL*brightness))))))
	luminosity = float64(math.Max(float64(0), float64(float64(math.Min(float64(1), float64(luminosity*brightness))))))
	luminosity *= float64(2)
	var cond270 float64
	if luminosity <= 1 {
		cond270 = luminosity
	} else {
		cond270 = 2 - luminosity
	}
	saturationHSL *= cond270
	value[0] = (luminosity + saturationHSL) / 2
	saturationHSV[0] = (2 * saturationHSL) / (luminosity + saturationHSL)
	if gtk.GTKGTK4 {
		var r []float32 = make([]float32, 1)
		var g []float32 = make([]float32, 1)
		var b []float32 = make([]float32, 1)
		gtk.GTK4Gtk_hsv_to_rgb(float32(hue[0]), float32(saturationHSV[0]), float32(value[0]), r, g, b)
		newRGBA.Red = float64(r[0])
		newRGBA.Green = float64(g[0])
		newRGBA.Blue = float64(b[0])
	} else {
		gtk.GTK3Gtk_hsv_to_rgb(hue[0], saturationHSV[0], value[0], hue, saturationHSV, value)
		newRGBA.Red = hue[0]
		newRGBA.Green = saturationHSV[0]
		newRGBA.Blue = value[0]
	}
	return newRGBA
}

func (this *Display) StyleContextEstimateBackgroundColor(context int64, state int32) gtk.GdkRGBA {
	gtk.GTKGtk_style_context_save(context)
	gtk.GTKGtk_style_context_set_state(context, int64(state))
	var surface int64 = gtk.CairoCairo_image_surface_create(gtk.CairoCAIRO_FORMAT_ARGB32, 1, 1)
	var cairo int64 = gtk.CairoCairo_create(surface)
	DisplayRenderAllBackgrounds(context, cairo)
	gtk.CairoCairo_fill(cairo)
	gtk.CairoCairo_surface_flush(surface)
	var buffer []int8 = make([]int8, 4)
	gtk.CMemmoveOverload8(buffer, gtk.CairoCairo_image_surface_get_data(surface), int64(int32(len(buffer))))
	gtk.CairoCairo_surface_destroy(surface)
	gtk.CairoCairo_destroy(cairo)
	gtk.GTKGtk_style_context_restore(context)
	var a int32 = int32(uint8(buffer[3]))
	var r int32 = int32(uint8(buffer[2]))
	var g int32 = int32(uint8(buffer[1]))
	var b int32 = int32(uint8(buffer[0]))
	var rgba gtk.GdkRGBA = gtk.GdkRGBA{}
	rgba.Alpha = float64(float32(a) / 255)
	rgba.Red = float64(float32(DisplayInversePremultipliedColor(r, a)) / 255)
	rgba.Green = float64(float32(DisplayInversePremultipliedColor(g, a)) / 255)
	rgba.Blue = float64(float32(DisplayInversePremultipliedColor(b, a)) / 255)
	return rgba
}

func (this *Display) CopyRGBA(source gtk.GdkRGBA) gtk.GdkRGBA {
	var retRGBA gtk.GdkRGBA = gtk.GdkRGBA{}
	if source != (gtk.GdkRGBA{}) {
		retRGBA.Alpha = source.Alpha
		retRGBA.Red = source.Red
		retRGBA.Green = source.Green
		retRGBA.Blue = source.Blue
	}
	return retRGBA
}

func (this *Display) InitializeSystemColors() {
	this.COLOR_WIDGET_DARK_SHADOW_RGBA = gtk.GdkRGBA{}
	this.COLOR_WIDGET_DARK_SHADOW_RGBA.Alpha = 1.0
	this.InitializeNamedColorList()
	var shellContext int64 = gtk.GTKGtk_widget_get_style_context(this.shellHandle)
	this.InitializeSystemColorsWidget(shellContext)
	this.InitializeSystemColorsList(shellContext)
	this.InitializeSystemColorsTitle(shellContext)
	this.InitializeSystemColorsLink()
	this.InitializeSystemColorsTooltip()
	this.InitializeSystemColorsToggleButton()
	this.InitializeSystemColorsDisabled()
	this.COLOR_TITLE_FOREGROUND_RGBA = this.COLOR_LIST_SELECTION_TEXT_RGBA
	this.COLOR_TITLE_BACKGROUND_RGBA = this.COLOR_LIST_SELECTION_RGBA
	this.COLOR_TITLE_BACKGROUND_GRADIENT_RGBA = this.ToGdkRGBA(this.COLOR_LIST_SELECTION_RGBA, 1.3)
	this.COLOR_TITLE_INACTIVE_BACKGROUND_GRADIENT_RGBA = this.ToGdkRGBA(this.COLOR_TITLE_INACTIVE_BACKGROUND_RGBA, 1.3)
}

func (this *Display) InitializeSystemColorsWidget(shellContext int64) {
	this.COLOR_WIDGET_FOREGROUND_RGBA = this.StyleContextGetColor(shellContext, gtk.GTKGTK_STATE_FLAG_NORMAL)
	this.COLOR_WIDGET_BACKGROUND_RGBA = this.StyleContextEstimateBackgroundColor(shellContext, gtk.GTKGTK_STATE_FLAG_NORMAL)
	this.COLOR_WIDGET_LIGHT_SHADOW_RGBA = this.COLOR_WIDGET_BACKGROUND_RGBA
	this.COLOR_WIDGET_NORMAL_SHADOW_RGBA = this.ToGdkRGBA(this.COLOR_WIDGET_BACKGROUND_RGBA, 0.7)
	this.COLOR_WIDGET_HIGHLIGHT_SHADOW_RGBA = this.ToGdkRGBA(this.COLOR_WIDGET_BACKGROUND_RGBA, 1.3)
}

func (this *Display) InitializeSystemColorsList(shellContext int64) {
	gtk.GTKGtk_style_context_save(shellContext)
	gtk.GTKGtk_style_context_add_class(shellContext, gtk.GTKGTK_STYLE_CLASS_VIEW)
	gtk.GTKGtk_style_context_add_class(shellContext, gtk.GTKGTK_STYLE_CLASS_CELL)
	this.COLOR_LIST_FOREGROUND_RGBA = this.StyleContextGetColor(shellContext, gtk.GTKGTK_STATE_FLAG_NORMAL)
	this.COLOR_LIST_BACKGROUND_RGBA = this.StyleContextEstimateBackgroundColor(shellContext, gtk.GTKGTK_STATE_FLAG_NORMAL)
	this.COLOR_LIST_SELECTION_TEXT_RGBA = this.StyleContextGetColor(shellContext, gtk.GTKGTK_STATE_FLAG_SELECTED|gtk.GTKGTK_STATE_FLAG_FOCUSED)
	this.COLOR_LIST_SELECTION_RGBA = this.StyleContextEstimateBackgroundColor(shellContext, gtk.GTKGTK_STATE_FLAG_SELECTED|gtk.GTKGTK_STATE_FLAG_FOCUSED)
	this.COLOR_LIST_SELECTION_TEXT_INACTIVE_RGBA = this.StyleContextGetColor(shellContext, gtk.GTKGTK_STATE_FLAG_SELECTED|gtk.GTKGTK_STATE_FLAG_BACKDROP)
	this.COLOR_LIST_SELECTION_INACTIVE_RGBA = this.StyleContextEstimateBackgroundColor(shellContext, gtk.GTKGTK_STATE_FLAG_SELECTED|gtk.GTKGTK_STATE_FLAG_BACKDROP)
	gtk.GTKGtk_style_context_restore(shellContext)
}

