func (this *Display) RemoveWidget(handle int64) *Widget {
	if handle == 0 {
		return nil
	}
	this.lastWidget = nil
	var widget *Widget = nil
	var index int32
	var data int64 = gtk.OSG_object_get_qdata(handle, DisplaySWT_OBJECT_INDEX) - 1
	if data < 0 || data > int64(math.MaxInt32) {
		ErrorCodeThrowableDetail(ERROR_INVALID_RETURN_VALUE, nil, fmt.Sprintf(". g_object_get_qdata returned unexpected index value%s", this.DebugInfoForIndex(data)))
	}
	index = int32(data)
	if 0 <= index && index < int32(len(this.widgetTable)) {
		widget = this.widgetTable[index]
		this.widgetTable[index] = nil
		this.indexTable[index] = this.freeSlot
		this.freeSlot = index
		gtk.OSG_object_set_qdata(handle, DisplaySWT_OBJECT_INDEX, int64(0))
		if widget == (nil) {
			ErrorCodeThrowableDetail(ERROR_INVALID_ARGUMENT, nil, fmt.Sprintf(". Widget already released%s", this.DebugInfoForIndex(int64(index))))
		}
	} else {
		ErrorCodeThrowableDetail(ERROR_INVALID_ARGUMENT, nil, fmt.Sprintf(". Invalid index for handle %d%s", handle, this.DebugInfoForIndex(int64(index))))
	}
	return widget
}

func (this *Display) DebugInfoForIndex(index int64) string {
	var s string = fmt.Sprintf(", index: %d", index)
	var idx int32 = int32(index)
	if idx >= 0 && idx < int32(len(this.widgetTable)) {
		s += fmt.Sprintf(", current value at: %v", this.widgetTable[idx])
	}
	s += this.DumpWidgetTableInfoManual()
	return s
}

