func (this *Display) Sleep() bool {
	this.impl.checkDevice_()
	if this.gdkEventCount == 0 {
		this.gdkEvents = nil
		this.gdkEventWidgets = nil
	}
	if this.settingsChanged {
		this.settingsChanged = false
		this.runSettings = true
		return false
	}
	if !this.synchronizer.IsMessagesEmpty() {
		return true
	}
	this.SendPreExternalEventDispatchEvent()
	if !gtk.GTKGTK4 {
		gtk.GDKGdk_threads_leave()
	}
	if this.fds == 0 {
		this.allocated_nfds = 2
		this.fds = gtk.OSG_malloc(int64(gtk.OSGPollFD_sizeof() * this.allocated_nfds))
	}
	this.timeout[0] = 0
	this.max_priority[0] = this.timeout[0]
	var context int64 = gtk.OSG_main_context_default()
	var result bool = false
	for {
		if gtk.OSG_main_context_acquire(context) {
			result = gtk.OSG_main_context_prepare(context, this.max_priority)
			var nfds int32
			for {
				cond290 := gtk.OSG_main_context_query(context, this.max_priority[0], this.timeout, this.fds, this.allocated_nfds)
				nfds = cond290
				if !((cond290) > this.allocated_nfds) {
					break
				}
				gtk.OSG_free(this.fds)
				this.allocated_nfds = nfds
				this.fds = gtk.OSG_malloc(int64(gtk.OSGPollFD_sizeof() * this.allocated_nfds))
			}
			var poll int64 = gtk.OSG_main_context_get_poll_func(context)
			if poll != 0 {
				if nfds > 0 || this.timeout[0] != 0 {
					if this.timeout[0] < 0 {
						this.timeout[0] = 50
					}
					this.wake = false
					gtk.OSCallProcII(poll, this.fds, nfds, this.timeout[0])
				}
			}
			gtk.OSG_main_context_check(context, this.max_priority[0], this.fds, nfds)
			gtk.OSG_main_context_release(context)
		}
		if !(!result && this.synchronizer.IsMessagesEmpty() && !this.wake) {
			break
		}
	}
	this.wake = false
	if !gtk.GTKGTK4 {
		gtk.GDKGdk_threads_enter()
	}
	this.SendPostExternalEventDispatchEvent()
	return true
}

